# dy.py: a tiny Dolev-Yao intruder. Terms are atoms (str) or tuples:
# ('tup', t1, t2, ...)  ('enc', msg, ('pk', X))  ('pk', X)  ('sk', X)
def analyse(knowledge):
    """Saturate: split tuples, decrypt with private keys we hold."""
    K, changed = set(knowledge), True
    while changed:
        changed = False
        for t in list(K):
            parts = []
            if isinstance(t, tuple) and t[0] == 'tup':
                parts = t[1:]
            elif isinstance(t, tuple) and t[0] == 'enc' and ('sk', t[2][1]) in K:
                parts = [t[1]]
            for p in parts:
                if p not in K: K.add(p); changed = True
    return K

def derivable(t, K):
    """Can the intruder build t from analysed knowledge K?"""
    if t in K: return True
    if isinstance(t, tuple) and t[0] in ('tup', 'enc'):
        return all(derivable(p, K) for p in t[1:])
    return False

def atoms(K):
    """Every atom that occurs anywhere inside known terms."""
    out, todo = set(), list(K)
    while todo:
        t = todo.pop()
        if isinstance(t, str): out.add(t)
        else: todo.extend(t[1:])
    return out

if __name__ == '__main__':
    K = analyse({'A', 'B', 'I', ('pk', 'A'), ('pk', 'B'), ('pk', 'I'),
                 ('sk', 'I'), ('enc', ('tup', 'Na', 'A'), ('pk', 'I')),
                 ('enc', ('tup', 'Na', 'Nb'), ('pk', 'A'))})
    print('Na' in K, 'Nb' in K)
    print(derivable(('enc', ('tup', 'Na', 'A'), ('pk', 'B')), K))
    print(derivable(('enc', 'Nb', ('pk', 'B')), K))

# ns_search.py: needs dy.py; any argument = Lowe's fix
import sys; from collections import deque
from dy import analyse, derivable, atoms
FIX = len(sys.argv) > 1
enc = lambda m, X: ('enc', m, ('pk', X))
tup = lambda *p: ('tup',) + p
def steps(a, peer, b, K):
    if a == 0:                  # A opens a run: B or I
        for p in 'BI':
            m = enc(tup('Na', 'A'), p); yield f'A->{p} {m}', (1, p, b, m)
    if b == 0:                  # B takes msg 1 "from A"
        for x in atoms(K):
            if derivable(enc(tup(x, 'A'), 'B'), K):
                m = enc(tup(x, 'Nb', 'B') if FIX else tup(x, 'Nb'), 'A')
                yield f'B->A {m}', (a, peer, 1, m)
    if a == 1:                  # A takes msg 2
        for y in atoms(K):
            if derivable(enc(tup('Na', y, peer) if FIX else tup('Na', y), 'A'), K):
                m = enc(y, peer); yield f'A->{peer} {m}', (2, peer, b, m)
    if b == 1 and derivable(enc('Nb', 'B'), K):
        yield 'B commits: peer is A', (a, peer, 2, None)
K0 = analyse({'A', 'B', 'I', ('pk', 'A'), ('pk', 'B'), ('pk', 'I'), ('sk', 'I')})
todo, seen = deque([((0, None, 0, frozenset(K0)), [])]), set()
while todo:
    (a, peer, b, K), trace = todo.popleft()
    if b == 2 and peer != 'B':  # A never ran with B
        print('ATTACK', *trace, f'Nb leaked: {"Nb" in K}', sep='\n '); break
    for label, (a2, p2, b2, m) in steps(a, peer, b, K):
        n = (a2, p2, b2, frozenset(analyse(K | {m}) if m else K))
        if n not in seen: seen.add(n); todo.append((n, trace + [label]))
else: print('no attack in', len(seen), 'states')

(* Needham-Schroeder public key, 3-message core (Lowe 1995/1996) *)
free c: channel.
type skey. type pkey. type host.
fun pk(skey): pkey.
fun aenc(bitstring, pkey): bitstring.
reduc forall m: bitstring, k: skey; adec(aenc(m, pk(k)), k) = m.
fun senc(bitstring, bitstring): bitstring.
reduc forall m: bitstring, k: bitstring; sdec(senc(m, k), k) = m.

free A, B, I: host.
free secretB: bitstring [private].
event beginI(host, host, bitstring).  (* A starts a run with peer *)
event endR(host, host, bitstring).    (* B accepts a run from A *)

query x: host, y: host, n: bitstring;
  inj-event(endR(x, y, n)) ==> inj-event(beginI(x, y, n)).
query attacker(secretB).

(* Initiator A talks to peer x whose public key is pkX *)
let initiator(skA: skey, x: host, pkX: pkey) =
  new na: bitstring;
  out(c, aenc((na, A), pkX));
  in(c, m2: bitstring);
  let (=na, nb: bitstring) = adec(m2, skA) in
  event beginI(A, x, nb);
  out(c, aenc(nb, pkX)).

(* Responder B accepts a run that claims to come from A *)
let responder(skB: skey, pkA: pkey) =
  in(c, m1: bitstring);
  let (na: bitstring, =A) = adec(m1, skB) in
  new nb: bitstring;
  out(c, aenc((na, nb), pkA));
  in(c, m3: bitstring);
  let (=nb) = adec(m3, skB) in
  event endR(A, B, nb);
  out(c, senc(secretB, nb)).   (* B now uses nb as a shared key *)

process
  new skA: skey; new skB: skey; new skI: skey;
  out(c, (pk(skA), pk(skB), skI));   (* attacker owns I's private key *)
  ( !initiator(skA, B, pk(skB)) | !initiator(skA, I, pk(skI))
  | !responder(skB, pk(skA)) )

