#include <stddef.h>

/* Leaky: returns at the first differing byte, so the run time
   tells an attacker how many leading bytes of a guess are right. */
int tag_equal_leaky(const unsigned char *a, const unsigned char *b, size_t n) {
    for (size_t i = 0; i < n; i++)
        if (a[i] != b[i]) return 0;
    return 1;
}

/* Fixed: always touches every byte and never branches on secret
   data; only the final yes/no answer depends on the tags. */
int tag_equal_ct(const unsigned char *a, const unsigned char *b, size_t n) {
    unsigned char diff = 0;
    for (size_t i = 0; i < n; i++)
        diff |= a[i] ^ b[i];
    return diff == 0;
}

int main(void) {
    unsigned char tag[4] = {0xde, 0xad, 0xbe, 0xef};
    unsigned char g1[4]  = {0xde, 0xad, 0x00, 0x00};
    unsigned char g2[4]  = {0xde, 0xad, 0xbe, 0xef};
    printf("leaky: %d %d   ct: %d %d\n", tag_equal_leaky(tag, g1, 4),
           tag_equal_leaky(tag, g2, 4), tag_equal_ct(tag, g1, 4),
           tag_equal_ct(tag, g2, 4));
    return 0;
}

# ct_check.py: a toy constant-time checker in the spirit of HACL*'s
# secret integers: secrets may flow into arithmetic, never into a
# branch condition, a loop condition or an array index.
import ast

def check(src, secrets):
    tainted, problems = set(secrets), []
    uses = lambda e: {n.id for n in ast.walk(e) if isinstance(n, ast.Name)}
    for node in ast.walk(ast.parse(src)):
        if isinstance(node, (ast.Assign, ast.AugAssign)):   # taint flows
            value_names = uses(node.value)
            if isinstance(node, ast.AugAssign):
                value_names |= uses(node.target)
            if value_names & tainted:
                targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                for t in targets: tainted |= uses(t)
        if isinstance(node, (ast.If, ast.While)) and uses(node.test) & tainted:
            problems.append(f'line {node.lineno}: branch on secret')
        if isinstance(node, ast.Subscript) and uses(node.slice) & tainted:
            problems.append(f'line {node.lineno}: secret array index')
    return problems or ['ok: no secret-dependent branch or index']

