/* From Yang et al., PLDI 2011: CompCert 1.6 for PowerPC returned 0 here. */
int bar(unsigned x) {
    return -1 <= (1 && x);   /* (1 && x) is an int, 0 or 1; -1 <= 0 or 1 */
}
int main(void) {
    printf("bar(0) = %d, bar(7) = %d\n", bar(0), bar(7));
    return 0;
}

# revoke.py: the Revoke spec as a Python breadth-first state explorer.
from collections import deque
R = ('r1', 'r2')

def next_states(s, wait_for_acks, durable):
    sent, known, acks, done, bad = s
    if not sent:
        yield 'SendRevoke', (True, known, acks, done, bad)
    for i, r in enumerate(R):
        if sent and not known[i]:
            k = known[:i] + (True,) + known[i+1:]
            yield f'Deliver({r})', (sent, k, acks | {r}, done, bad)
        if not known[i]:                       # replica accepts the token
            yield f'Accept({r})', (sent, known, acks, done, bad or done)
        k = known[:i] + (durable and known[i],) + known[i+1:]
        yield f'Restart({r})', (sent, k, acks, done, bad)
    if sent and not done and (not wait_for_acks or acks == frozenset(R)):
        yield 'Confirm', (sent, known, acks, True, bad)

def check(wait_for_acks, durable):
    init = (False, (False, False), frozenset(), False, False)
    todo, seen = deque([(init, [])]), {init}
    while todo:
        s, trace = todo.popleft()
        if s[4]:                               # invariant ~badAccept broken
            return 'VIOLATED: ' + ' -> '.join(trace)
        for label, n in next_states(s, wait_for_acks, durable):
            if n not in seen:
                seen.add(n); todo.append((n, trace + [label]))
    return f'holds in all {len(seen)} reachable states'

for w, d in ((False, False), (True, False), (True, True)):
    print(f'WaitForAcks={w!s:5} Durable={d!s:5}', check(w, d))
